import * as React from "react";
import styles from "./HodViewScorecardDetail.module.scss"; 


const ReviewScorecardCandidateList: React.FC<any> = ({ candidateList, onViewDetail, stateValue, isLoading, navigateBack }) => {
  return (
      <div className={styles.tablePage}>
        <div className={styles.tableHeaderSection}>
          <div>
            <h1>{stateValue?.JobCode} - Candidates</h1>
            <p>{stateValue?.Department}</p>
          </div>
          <button className={styles.outlineBtn} onClick={navigateBack}>Back to Jobs</button>
        </div>

        <div className={styles.tableContainer}>
          <table className={styles.modernTable}>
            <thead>
              <tr>
                <th>Candidate Name</th>
                <th>Nationality</th>
                <th>Exp.</th>
                <th>Status</th>
                <th>Action</th>
              </tr>
            </thead>
            <tbody>
              {candidateList?.map((cand: any, idx: number) => (
                <tr key={idx}>
                  <td className={styles.boldText}>{cand.CandidateName}</td>
                  <td>{cand.Nationality}</td>
                  <td>{cand.TotalExperience} Yrs</td>
                  <td>
                    <span className={`${styles.badge} ${styles[cand.Status?.replace(/\s/g, "")]}`}>
                      {cand.Status}
                    </span>
                  </td>
                  <td>
                    <button className={styles.actionBtn} onClick={() => onViewDetail(cand)}>
                      View Detail
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
  );
};

export default ReviewScorecardCandidateList;